```json
{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, attr_span_kind, service_name, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' GROUP BY 1,2,3", "claim": "search's rate.Rate/GetRates client p95 is about 2205 ms in the abnormal window; rate's server spans stay around 1.2 ms."},
        {"kind": "trace", "sql": "WITH c AS (SELECT span_id, time, duration FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND attr_span_kind='Client'), s AS (SELECT parent_span_id, time, duration FROM abnormal_traces WHERE span_name='rate.Rate/GetRates' AND attr_span_kind='Server') SELECT count(*) n, avg(c.duration)/1e6 client_ms, avg(s.duration)/1e6 server_ms, approx_quantile(EPOCH_MS(s.time)-EPOCH_MS(c.time),0.5) median_start_gap_ms FROM c JOIN s ON c.span_id = s.parent_span_id", "claim": "Rate server span starts about 1.5 s after the search client span, yet runs in about 0.6 ms; the delay sits before the server."},
        {"kind": "trace", "sql": "WITH cl AS (SELECT span_id, span_name, service_name, time, duration FROM abnormal_traces WHERE attr_span_kind='Client'), sv AS (SELECT parent_span_id, service_name, time, duration FROM abnormal_traces WHERE attr_span_kind='Server') SELECT cl.service_name caller, cl.span_name, sv.service_name callee, count(*) n, avg(EPOCH_MS(sv.time)-EPOCH_MS(cl.time)) start_gap_ms FROM cl JOIN sv ON cl.span_id=sv.parent_span_id WHERE cl.service_name='search' GROUP BY 1,2,3", "claim": "Only search's connection to rate shows a start gap of over a second; search to geo shows about 0.2 ms."}
      ]
    }
  ],
  "propagation": [
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name IN ('HTTP /hotels','HTTP /recommendations','search.Search/Nearby') GROUP BY 1,2,3", "claim": "Frontend /hotels and its search.Search/Nearby client spans reach about 2.2 s p95, while /recommendations stays near 1.2 ms."}]}
  ]
}
